mapper.sql:
SELECT s.id AS submission_id, s.exam_id, e.title AS exam_name, s.student_id, u.name AS student_name, u.username AS student_no, s.status AS submission_status, s.submit_time, s.total_score, COUNT(q.id) AS manual_required_count, SUM(CASE WHEN a.grading_status = 'REVIEWED' AND a.teacher_score IS NOT NULL THEN 1 ELSE 0 END) AS manual_reviewed_count, COUNT(q.id) AS ai_required_count, SUM(CASE WHEN ai.status = 'SUCCESS' THEN 1 ELSE 0 END) AS ai_success_count, SUM(CASE WHEN ai.status = 'FAILED' THEN 1 ELSE 0 END) AS ai_failed_count, SUM(CASE WHEN ai.status = 'NOT_CONFIGURED' THEN 1 ELSE 0 END) AS ai_not_configured_count, SUM(CASE WHEN q.id IS NOT NULL AND ai.id IS NULL THEN 1 ELSE 0 END) AS ai_no_result_count, COALESCE(s.score_published = 1, 0) AS score_published, (e.results_released_at IS NOT NULL) AS results_released FROM submissions s JOIN exams e ON e.id = s.exam_id JOIN courses c ON c.id = e.course_id AND c.teacher_id = #{teacherId} JOIN users u ON u.id = s.student_id LEFT JOIN questions q ON q.exam_id = e.id AND q.question_type = 'SHORT_ANSWER' LEFT JOIN answers a ON a.submission_id = s.id AND a.question_id = q.id LEFT JOIN ai_grading_results ai ON ai.answer_id = a.id WHERE s.status IN ('SUBMITTED', 'AUTO_SUBMITTED', 'GRADED') AND s.exam_id = #{query.examId}
AND (u.name LIKE #{query.keywordPattern} ESCAPE '!' OR u.username LIKE #{query.keywordPattern} ESCAPE '!')
GROUP BY s.id, s.exam_id, e.title, s.student_id, u.name, u.username, s.status, s.submit_time, s.total_score, s.score_published, e.results_released_at

mapper.select:
SELECT t.* FROM () t

ORDER BY t.submit_time DESC, t.submission_id DESC
LIMIT #{query.size} OFFSET #{query.offset}
